effect.shader:
void main(){
    vec2 ctr = center/1000.0 + 0.5;
    vec2 d = acScreenNorm - ctr;
    d.x *= acScreenSize.x/acScreenSize.y;
    float r = length(d);
    float a = radians(angle) * (1.0 - smoothstep(0.0, radius, r));
    float s=sin(a), co=cos(a);
    d = mat2(co,-s,s,co)*d;
    d.x /= acScreenSize.x/acScreenSize.y;
    gl_FragColor = texture2DCv(inputImg.texture, ctr+d);
}
